"""Deterministic M08 geometry executor; built by Actions, never generated by a model at runtime."""
from __future__ import annotations
import hashlib,html,json,uuid,math
from pathlib import Path
from .design_job import load,canonical,require

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def export_ifc(state,path):
    import ifcopenshell
    import ifcopenshell.api.aggregate,ifcopenshell.api.context,ifcopenshell.api.geometry
    import ifcopenshell.api.project,ifcopenshell.api.root,ifcopenshell.api.spatial,ifcopenshell.api.unit
    import numpy as np
    f=ifcopenshell.api.project.create_file(version="IFC4")
    pr=ifcopenshell.api.root.create_entity(f,ifc_class="IfcProject",name=state["job"]["project_id"]+" SYNTHETIC")
    unit=ifcopenshell.api.unit.add_si_unit(f,unit_type="LENGTHUNIT")
    ifcopenshell.api.unit.assign_unit(f,units=[unit])
    model=ifcopenshell.api.context.add_context(f,context_type="Model")
    body=ifcopenshell.api.context.add_context(f,context_type="Model",context_identifier="Body",
                                              target_view="MODEL_VIEW",parent=model)
    site=ifcopenshell.api.root.create_entity(f,ifc_class="IfcSite",name="Synthetic QA only")
    building=ifcopenshell.api.root.create_entity(f,ifc_class="IfcBuilding",name="Synthetic test structure")
    ifcopenshell.api.aggregate.assign_object(f,relating_object=pr,products=[site])
    ifcopenshell.api.aggregate.assign_object(f,relating_object=site,products=[building])
    storeys={}
    mapping={"footing":"IfcFooting","column":"IfcColumn","beam":"IfcBeam","slab":"IfcSlab","wall":"IfcWall"}
    for name in state["levels"]:
        storey=ifcopenshell.api.root.create_entity(f,ifc_class="IfcBuildingStorey",name=name)
        storey.Elevation=state["levels"][name]/1000
        ifcopenshell.api.aggregate.assign_object(f,relating_object=building,products=[storey])
        storeys[name]=storey
    created={}
    def gid(s):
        return ifcopenshell.guid.compress(uuid.uuid5(uuid.NAMESPACE_URL,
            state["job"]["project_id"]+"/M08/"+s).hex)
    def extrude(element,dimension,translation):
        profile=f.create_entity("IfcRectangleProfileDef",ProfileType="AREA",
             XDim=dimension[0]/1000,YDim=dimension[1]/1000)
        rep=ifcopenshell.api.geometry.add_profile_representation(f,context=body,
             profile=profile,depth=dimension[2]/1000)
        ifcopenshell.api.geometry.assign_representation(f,product=element,representation=rep)
        matrix=np.eye(4);matrix[:3,3]=[n/1000 for n in translation]
        ifcopenshell.api.geometry.edit_object_placement(f,product=element,matrix=matrix,is_si=True)
    for e in state["elements"]:
        item=ifcopenshell.api.root.create_entity(f,ifc_class=mapping[e["kind"]],name=e["id"])
        item.Tag=e["id"]
        item.GlobalId=gid(e["id"])
        item.Description="SYNTHETIC_QA_ONLY | NON-CONSTRUCTION DESIGN JOB"
        extrude(item,[e["length_mm"],e["width_mm"],e["height_mm"]],
           [e["x_mm"]+e["length_mm"]/2,e["y_mm"]+e["width_mm"]/2,e["z_mm"]])
        ifcopenshell.api.spatial.assign_container(f,relating_structure=storeys[e["level_id"]],products=[item])
        created[e["id"]]=item
    for opening in state["openings"]:
        w=state["by_id"][opening["host_id"]]
        item=ifcopenshell.api.root.create_entity(f,ifc_class="IfcOpeningElement",name=opening["id"])
        item.GlobalId=gid(opening["id"]);item.Tag=opening["id"]
        item.Description="SYNTHETIC_QA_ONLY | OPENING_IN_WALL"
        extrude(item,[opening["width_mm"],w["width_mm"]+4,opening["height_mm"]],
            [w["x_mm"]+opening["offset_mm"]+opening["width_mm"]/2,
             w["y_mm"]+w["width_mm"]/2,w["z_mm"]+opening["sill_mm"]])
        f.create_entity("IfcRelVoidsElement",GlobalId=gid("VOID-"+opening["id"]),
           RelatingBuildingElement=created[opening["host_id"]],RelatedOpeningElement=item)
    f.write(str(path))
    return {"format":"IFC4","engine":"IfcOpenShell","element_count":len(created),
            "opening_count":len(state["openings"])}
def make_occt(state):
    from OCP.BRepPrimAPI import BRepPrimAPI_MakeBox
    from OCP.BRepAlgoAPI import BRepAlgoAPI_Cut
    from OCP.BRep import BRep_Builder
    from OCP.TopoDS import TopoDS_Compound
    from OCP.gp import gp_Pnt
    assembly=TopoDS_Compound();builder=BRep_Builder();builder.MakeCompound(assembly)
    for e in state["elements"]:
        x=e["x_mm"];y=e["y_mm"];z=e["z_mm"]
        shape=BRepPrimAPI_MakeBox(gp_Pnt(x,y,z),gp_Pnt(x+e["length_mm"],y+e["width_mm"],z+e["height_mm"])).Shape()
        for o in state["openings"]:
            if o["host_id"]!=e["id"]:continue
            cutter=BRepPrimAPI_MakeBox(
                gp_Pnt(x+o["offset_mm"],y-2,z+o["sill_mm"]),
                gp_Pnt(x+o["offset_mm"]+o["width_mm"],y+e["width_mm"]+2,
                       z+o["sill_mm"]+o["height_mm"])).Shape()
            operation=BRepAlgoAPI_Cut(shape,cutter);operation.Build()
            require(operation.IsDone(),"OpenCascade opening boolean failed")
            shape=operation.Shape()
        builder.Add(assembly,shape)
    return assembly
def export_step(state,path):
    from OCP.STEPControl import STEPControl_Writer,STEPControl_AsIs
    from OCP.IFSelect import IFSelect_RetDone
    writer=STEPControl_Writer()
    require(writer.Transfer(make_occt(state),STEPControl_AsIs)==IFSelect_RetDone,"STEP transfer")
    require(writer.Write(str(path))==IFSelect_RetDone,"STEP write")
    return {"format":"STEP_BREP","engine":"OpenCascade/OCP","element_count":len(state["elements"]),
            "opening_count":len(state["openings"])}
def export_dxf(state,path):
    import ezdxf
    doc=ezdxf.new("R2013");doc.units=4
    for name,color in (("FOOTING",1),("COLUMN",3),("BEAM",2),("SLAB",8),("WALL",7),("OPENING_REVIEW",6)):
        doc.layers.new(name,dxfattribs={"color":color})
    doc.appids.new("FABIN_CAD")
    for e in state["elements"]:
        x=e["x_mm"];y=e["y_mm"];l=e["length_mm"];w=e["width_mm"]
        entity=doc.modelspace().add_lwpolyline([(x,y),(x+l,y),(x+l,y+w),(x,y+w)],
             close=True,dxfattribs={"layer":e["kind"].upper()})
        entity.set_xdata("FABIN_CAD",[(1000,e["id"]),(1000,"SYNTHETIC_QA_ONLY")])
    for o in state["openings"]:
        w=state["by_id"][o["host_id"]];x=w["x_mm"]+o["offset_mm"]
        ent=doc.modelspace().add_line((x,w["y_mm"]-10),(x+o["width_mm"],w["y_mm"]-10),
                       dxfattribs={"layer":"OPENING_REVIEW"})
        ent.set_xdata("FABIN_CAD",[(1000,o["id"]),(1000,o["host_id"]),(1000,"SCHEMATIC_PLAN_MARKER_ONLY")])
    doc.saveas(str(path))
    return {"format":"DXF_PLAN","engine":"ezdxf","element_count":len(state["elements"]),
            "opening_count":len(state["openings"]),"opening_display":"ANNOTATION_NOT_PLAN_BOOLEAN"}
def svg_plan(state):
    els=state["elements"];xs=[v for e in els for v in (e["x_mm"],e["x_mm"]+e["length_mm"])]
    ys=[v for e in els for v in (e["y_mm"],e["y_mm"]+e["width_mm"])]
    left=min(xs)-700;bottom=min(ys)-700;width=max(xs)-min(xs)+1400;height=max(ys)-min(ys)+1400
    colors={"footing":"#de9a50","column":"#0c7892","beam":"#b48f34","slab":"#c4e1e5","wall":"#27364a"}
    rects=[]
    for e in sorted(els,key=lambda x:{"slab":0,"footing":1,"beam":2,"wall":3,"column":4}[x["kind"]]):
        x=e["x_mm"];y=e["y_mm"]
        rects.append(f'<rect x="{x}" y="{y}" width="{e["length_mm"]}" height="{e["width_mm"]}" fill="{colors[e["kind"]]}" fill-opacity=".55" stroke="#14364b" stroke-width="30"/>')
        rects.append(f'<text x="{x+30}" y="{y+min(e["width_mm"]/2,450)}" fill="#132c3c" font-size="240">{html.escape(e["id"])}</text>')
    for o in state["openings"]:
        w=state["by_id"][o["host_id"]]
        rects.append(f'<line x1="{w["x_mm"]+o["offset_mm"]}" y1="{w["y_mm"]}" x2="{w["x_mm"]+o["offset_mm"]+o["width_mm"]}" y2="{w["y_mm"]}" stroke="#c72b56" stroke-width="75" stroke-dasharray="160,90"/>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{left} {bottom} {width} {height}" role="img" aria-label="Synthetic plan review" width="100%"><rect x="{left}" y="{bottom}" width="{width}" height="{height}" fill="#f5fafc"/>{"".join(rects)}</svg>'
def svg_section(state):
    els=state["elements"]
    plane=state["source"]["section_y_mm"]
    subset=[e for e in els if e["y_mm"]<=plane<=e["y_mm"]+e["width_mm"]]
    require(bool(subset),"section plane intersects no solid")
    xx=[v for e in subset for v in (e["x_mm"],e["x_mm"]+e["length_mm"])]
    zz=[v for e in subset for v in (e["z_mm"],e["z_mm"]+e["height_mm"])]
    left=min(xx)-400;bottom=min(zz)-400;w=max(xx)-min(xx)+800;h=max(zz)-min(zz)+800
    rects=[]
    for e in subset:
        rects.append(f'<rect x="{e["x_mm"]}" y="{-(e["z_mm"]+e["height_mm"])}" width="{e["length_mm"]}" height="{e["height_mm"]}" fill="#9bb7c8" stroke="#274b62" stroke-width="25"/>')
        if e["kind"]=="wall":
            for o in state["openings"]:
                if o["host_id"]==e["id"]:
                    rects.append(f'<rect x="{e["x_mm"]+o["offset_mm"]}" y="{-(e["z_mm"]+o["sill_mm"]+o["height_mm"])}" width="{o["width_mm"]}" height="{o["height_mm"]}" fill="#f5fafc" stroke="#c72b56" stroke-width="30"/>')
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{left} {-max(zz)-400} {w} {h}" role="img" aria-label="Synthetic actual axis-aligned section at Y={plane}mm" width="100%"><rect x="{left}" y="{-max(zz)-400}" width="{w}" height="{h}" fill="#f5fafc"/>{"".join(rects)}</svg>'
def build(job_path,root,out):
    target=Path(out)
    require(not target.exists() or not any(target.iterdir()),"target must be empty")
    state=load(job_path,root)
    target.mkdir(parents=True,exist_ok=True)
    outputs=[]
    for name,executor in (("design.ifc",export_ifc),("design.step",export_step),("design.dxf",export_dxf)):
        path=target/name
        result=executor(state,path)
        require(path.stat().st_size>100,"generated artifact empty")
        outputs.append({**result,"name":name,"sha256":sha(path),"bytes":path.stat().st_size})
    plan=svg_plan(state);section=svg_section(state)
    (target/"plan.svg").write_text(plan,encoding="utf8")
    (target/"section.svg").write_text(section,encoding="utf8")
    for name in ("plan.svg","section.svg"):
        p=target/name;outputs.append({"name":name,"sha256":sha(p),"bytes":p.stat().st_size,"format":"SVG_REVIEW"})
    preview='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>M08 Machine CAD · SYNTHETIC QA</title><style>body{font:16px system-ui;background:#f2f7fb;color:#18354a;max-width:1040px;margin:auto;padding:24px}figure{background:white;padding:15px;border-radius:12px}svg{height:auto;max-height:650px}small{color:#96401d}</style><h1>Machine-built geometry · Synthetic QA</h1><p><strong>Not a real building. Not approved for construction.</strong> Source SHA-256 and geometric checks enforced by GitHub Actions.</p><figure><h2>Plan</h2>'+plan+'</figure><figure><h2>Section at Y='+str(state["source"]["section_y_mm"])+' mm</h2>'+section+'</figure><small>Output is created deterministically from a checked-in synthetic source. DXF opening markers are plan annotations; actual 3D voids are represented in IFC and OpenCascade STEP.</small></html>'
    (target/"index.html").write_text(preview,encoding="utf8")
    p=target/"index.html";outputs.append({"name":"index.html","sha256":sha(p),"bytes":p.stat().st_size,"format":"HTML_STATIC"})
    manifest={"schema":"fabin-cad://design-result/0.1","job_id":state["job"]["job_id"],
      "project_id":state["job"]["project_id"],"status":"SYNTHETIC_QA_ONLY","source_sha256":state["source_sha256"],
      "job_sha256":sha(job_path),"elements":len(state["elements"]),"openings":len(state["openings"]),
      "engineering_approval":"HOLD","quantity_takeoff":"BLOCKED","ai_geometry_generation":"NONE",
      "outputs":outputs}
    (target/"manifest.json").write_bytes(canonical(manifest))
    return manifest
